```bash
npm install discord.js@14
```

A continuación, crea un archivo `index.js` y agrega el siguiente código:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log(`Bot ${client.user.username} listo para funcionar.`);
});

client.on('messageCreate', async (message) => {
  if (!message.content.startsWith('\/')) return;

  const args = message.content.slice(1).trim().split(' ');
  const command = args.shift()?.toLowerCase();

  if (command === 'ban') {
    if (!message.member.permissions.has('BAN_MEMBERS')) {
      return message.reply('No tienes los permisos necesarios para usar este comando.');
    }

    if (!args.length) {
      return message.reply('Por favor, proporciona un usuario a banear.');
    }

    const user = await message.guild.members.fetch(args[0]);

    if (!user.bannable) {
      return message.reply('Este usuario no puede ser baneado.');
    }

    await message.guild.bans.create(user);

    return message.reply(`${user.user.tag} ha sido baneado del servidor.`);
  }
});

client.login(process.env.TOKEN);
```

Recuerda reemplazar `process.env.TOKEN` por la cadena de tu token de bot de Discord.

Para que el bot se conecte al servidor, asegúrate de haber configurado correctamente tus credenciales en un archivo `.env` con el siguiente contenido:

```
TOKEN=<TU_TOKEN_DE_DISCORD>
```

Luego, ejecuta el script en la terminal con el siguiente comando:

```bash
node index.js
``` 

Ahora, tu bot estará listo para recibir comandos de forma asíncrona con la barra diagonal `/ban` en tu servidor de Discord. ¡Asegúrate de tener los permisos necesarios para usar este comando!

