5. Implementar la lógica del juego: Implementa la lógica del juego, incluyendo la creación y movimiento de la serpiente, la generación de comida aleatoria, la detección de colisiones con el borde y la comida, y la muerte de la serpiente.

```c
Snake snake;
SnakeSegment *new_segment;

// Initialize snake
snake.body = malloc(sizeof(SnakeSegment));
snake.body[0].x = 320;
snake.body[0].y = 240;
snake.length = 1;
snake.direction = 0;

// Generate random food
int food_x, food_y;
do {
    food_x = rand() % 30 * 20 + 10;
    food_y = rand() % 20 * 20 + 10;
} while (collidesWithSnake(food_x, food_y));

// Function to check if a point collides with the snake
int collidesWithSnake(int x, int y) {
    for (int I = 1; I < snake.length; i++) {
        if (snake.body[i].x == x && snake.body[i].y == y) {
            return 1;
        }
    }
    return 0;
}

// Main game loop
while (true) {
    // Move snake
    for (int I = snake.length - 1; I > 0; i--) {
        snake.body[i].x = snake.body[i - 1].x;
        snake.body[i].y = snake.body[i - 1].y;
    }

    switch (snake.direction) {
        case 0: // Right
            snake.body[0].x += 20;
            break;
        case 1: // Down
            snake.body[0].y += 20;
            break;
        case 2: // Left
            snake.body[0].x -= 20;
            break;
        case 3: // Up
            snake.body[0].y -= 20;
            break;
    }

    // Check for collision with border
    if (snake.body[0].x < 10 || snake.body[0].x > 630 || snake.body[0].y < 10 || snake.body[0].y > 470) {
        // Game over
        // ...
    }

    // Check for collision with food
    if (snake.body[0].x == food_x && snake.body[0].y == food_y) {
        // Add a new segment to the snake
        new_segment = malloc(sizeof(SnakeSegment));
        new_segment->x = snake.body[snake.length - 1].x;
        new_segment->y = snake.body[snake.length - 1].y;
        snake.length++;
        snake.body = realloc(snake.body, sizeof(SnakeSegment) * snake.length);

        snake.body[snake.length - 1] = *new_segment;

        // Generate new food
        do {
            food_x = rand() % 30 * 20 + 10;
            food_y = rand() % 20 * 20 + 10;
        } while (collidesWithSnake(food_x, food_y));
    }
}
```

